def hex_word_sum(input_string):
    def hex_value(word):
        hex_map = {'O': '0', 'S': '5'}
        for old, new in hex_map.items():
            word = word.replace(old, new)
        try:
            return int(word, 16)
        except ValueError:
            return 0

    words = input_string.split()
    return sum(hex_value(word) for word in words)

# Example usage:
print(hex_word_sum('BAG OF BEES'))  # Output: 48884
